// External spur gears generated by a rounded rack cutter.
// Units in mm until the final outline is converted to document cm.
const TAU=2*Math.PI;
function simplifyGearPiece(points,tolerance){
  if(points.length<3||!tolerance)return points;
  const a=points[0],b=points.at(-1),dx=b.u-a.u,dy=b.v-a.v,length2=dx*dx+dy*dy;
  let farthest=-1,distance=0;
  for(let i=1;i<points.length-1;i++){
    const p=points[i],t=length2?Math.max(0,Math.min(1,((p.u-a.u)*dx+(p.v-a.v)*dy)/length2)):0;
    const d=Math.hypot(p.u-a.u-t*dx,p.v-a.v-t*dy);
    if(d>distance){distance=d;farthest=i;}
  }
  if(distance<=tolerance)return [a,b];
  return simplifyGearPiece(points.slice(0,farthest+1),tolerance).slice(0,-1).concat(simplifyGearPiece(points.slice(farthest),tolerance));
}
export function rackGearSpec(spec){
  const m=Number(spec.moduleMm),z=Number(spec.teeth),alpha=Number(spec.pressureAngleDeg??20)*Math.PI/180;
  const depth=Number(spec.cutter?.addendumCoefficient??1.25)*m,rho=Number(spec.cutter?.tipRadiusCoefficient??.38)*m,backlash=Number(spec.backlashMm??0);
  if(!(m>0)||!Number.isInteger(z)||z<5||z>400||!(alpha>0&&alpha<Math.PI/4)||!Number.isFinite(depth)||!Number.isFinite(rho)||!(depth>m)||rho<=0||rho>=depth||!Number.isFinite(backlash)||backlash<0||backlash>=m*.5)throw new Error('Invalid rack cutter or gear dimensions');
  const profileShift=Number(spec.profileShift??0);
  if(!Number.isFinite(profileShift)||Math.abs(profileShift)>1)throw new Error('Profile shift must be between -1 and 1');
  const shift=profileShift*m;
  const rp=m*z/2,rb=rp*Math.cos(alpha),ra=rp+m+shift,rf=rp-depth+shift,half=Math.PI*m/4+backlash/4-shift*Math.tan(alpha);
  const yc=-depth+rho+shift,xc=half+yc*Math.tan(alpha)-rho/Math.cos(alpha),joinY=-depth+rho*(1-Math.sin(alpha))+shift;
  if(![rp,ra,rf,xc].every(Number.isFinite)||xc<=0||rf<=0||ra<=rb)throw new Error('Cutter tip does not fit the tooth space');
  const undercut=-joinY>rp*Math.sin(alpha)**2+1e-9;
  return {m,z,alpha,profileShift,depth,rho,backlash,rp,rb,ra,rf,half,xc,yc,joinY,undercut};
}
export function generatedRackGear(spec){
  const s=rackGearSpec(spec);if(s.undercut&&spec.allowUndercut!==true)throw new Error('Rack cutter would undercut this gear; increase tooth count or change the cutter');
  const {rp,ra,rf,alpha,rho,xc,yc,half,z,joinY}=s;
  // Rolling transform R(t) (x + rp*t, rp+y). Envelope requires
  // x'(x+rp*t)+y'y=0. Thus the rack normal passes through the pitch point.
  const envelope=(x,y,dx,dy)=>{const X=-y*dy/dx,t=(X-x)/rp;return {r:Math.hypot(X,rp+y),phi:Math.abs(Math.atan2(rp+y,X)+t-Math.PI/2)};};
  const root=[];
  const samples=s.undercut?96:48;
  for(let i=0;i<=samples;i++){const a=-Math.PI/2+(Math.PI/2-alpha)*i/samples;root.push(envelope(xc+rho*Math.cos(a),yc+rho*Math.sin(a),-Math.sin(a),Math.cos(a)));}
  const topY=-rp*Math.sin(alpha)**2+Math.sin(alpha)*Math.sqrt(ra*ra-s.rb*s.rb),flank=[];
  const flankStart=s.undercut?-rp*Math.sin(alpha)**2:joinY;
  for(let i=s.undercut?0:1;i<=samples;i++){const y=flankStart+(topY-flankStart)*i/samples;flank.push(envelope(half+y*Math.tan(alpha),y,Math.tan(alpha),1));}
  let side=root.concat(flank),joinRadius=root.at(-1).r;
  if(s.undercut){
    // The raw envelope loops where the trochoid meets the usable involute.
    // Keep the outside boundary by intersecting the root with the ascending
    // involute branch; simply retaining the folded loop is not a tooth.
    const rootAt=a=>envelope(xc+rho*Math.cos(a),yc+rho*Math.sin(a),-Math.sin(a),Math.cos(a));
    const flankAtRadius=r=>{const y=-rp*Math.sin(alpha)**2+Math.sin(alpha)*Math.sqrt(Math.max(0,r*r-s.rb*s.rb));return {y,q:envelope(half+y*Math.tan(alpha),y,Math.tan(alpha),1)};};
    let low=-Math.PI/2,high=-alpha;
    for(let i=0;i<70;i++){const mid=(low+high)/2;if(rootAt(mid).r<s.rb)low=mid;else high=mid;}
    low=high;high=-alpha;
    const gap=a=>{const q=rootAt(a);return q.phi-flankAtRadius(q.r).q.phi;};
    if(gap(low)<-1e-10||gap(high)>1e-10)throw new Error('Undercut envelope has no resolved root/flank intersection');
    for(let i=0;i<70;i++){const mid=(low+high)/2;if(gap(mid)>0)low=mid;else high=mid;}
    const angle=(low+high)/2,q=rootAt(angle),join=flankAtRadius(q.r);
    side=[];
    for(let i=0;i<=samples;i++)side.push(rootAt(-Math.PI/2+(angle+Math.PI/2)*i/samples));
    for(let i=1;i<=samples;i++){const y=join.y+(topY-join.y)*i/samples;side.push(envelope(half+y*Math.tan(alpha),y,Math.tan(alpha),1));}
    joinRadius=q.r;
  }
  const phiRoot=side[0].phi,phiTip=side.at(-1).phi;
  if(side.some(q=>!Number.isFinite(q.r)||!Number.isFinite(q.phi))||phiTip>=Math.PI/z||side.some((q,i)=>i&&q.r<side[i-1].r-1e-7))throw new Error('Generated tooth is folded or has no tip land');
  const points=[],polar=(r,a)=>({u:r*Math.cos(a)/10,v:r*Math.sin(a)/10});
  const simplificationMm=Number(spec.outlineSimplificationMm??.002);
  if(!Number.isFinite(simplificationMm)||simplificationMm<0||simplificationMm>.01)throw new Error('Outline simplification must be between zero and 0.01 mm');
  const appendSide=(samples,angle)=>{
    const planar=samples.map(q=>polar(q.r,angle(q))),joinIndex=samples.findIndex(q=>Math.abs(q.r-joinRadius)<1e-9);
    // Preserve the root/involute junction, each tip, and each root-land endpoint.
    const pieces=joinIndex>0&&joinIndex<samples.length-1?[planar.slice(0,joinIndex+1),planar.slice(joinIndex)]:[planar];
    pieces.forEach((piece,i)=>{const compact=simplifyGearPiece(piece,simplificationMm/10);points.push(...(i?compact.slice(1):compact));});
  };
  for(let k=0;k<z;k++){
    const c=k*TAU/z;
    appendSide(side.slice().reverse(),q=>c-q.phi);
    for(let i=1;i<=12;i++)points.push(polar(rf,c-phiRoot+2*phiRoot*i/12));
    appendSide(side.slice(1),q=>c+q.phi);
    for(let i=1;i<12;i++)points.push(polar(ra,c+phiTip+(TAU/z-2*phiTip)*i/12));
  }
  return {points,spec:s,rootJoinRadiusMm:joinRadius,undercut:s.undercut,outlineSimplificationMm:simplificationMm,estimatedChordErrorMm:estimateChordError(s)+simplificationMm};
}
function estimateChordError(s){return Math.max(s.ra*(1-Math.cos(Math.PI/s.z/12)),s.m*.001);}
// Analytic operating contact and interference checks for external standard centres.
// This is geometry validation, not tooth bending/contact-stress certification.
export function validateGearPair(a,b){
  const issues=[];let A,B;
  try{A=generatedRackGear(a);B=generatedRackGear(b);}catch(error){return {ok:false,issues:[error.message]};}
  const p=A.spec,q=B.spec;
  if(Math.abs(p.m-q.m)>1e-9||Math.abs(p.alpha-q.alpha)>1e-9)issues.push('Mating gears require equal module and pressure angle');
  let operating;try{operating=gearOperatingGeometry(p,q);}catch(error){return {ok:false,issues:[...issues,error.message]};}
  const distance=operating.distance,alpha=operating.alpha;
  const r1=distance*p.z/(p.z+q.z),r2=distance*q.z/(p.z+q.z);
  const approach=Math.sqrt(q.ra*q.ra-q.rb*q.rb)-r2*Math.sin(alpha),recess=Math.sqrt(p.ra*p.ra-p.rb*p.rb)-r1*Math.sin(alpha);
  const contactRatio=(approach+recess)/(Math.PI*p.m*Math.cos(p.alpha));
  const availableA=r1*Math.sin(alpha)-Math.sqrt(Math.max(0,A.rootJoinRadiusMm**2-p.rb**2));
  const availableB=r2*Math.sin(alpha)-Math.sqrt(Math.max(0,B.rootJoinRadiusMm**2-q.rb**2));
  if(approach>availableA+1e-7||recess>availableB+1e-7)issues.push('Mating tip enters the generated root transition');
  if(contactRatio<1)issues.push('Contact ratio is below one');
  const tipClearanceMm=Math.min(distance-p.ra-q.rf,distance-q.ra-p.rf);
  if(tipClearanceMm<=0)issues.push('No positive tip-to-root clearance');
  return {ok:!issues.length,issues,contactRatio,tipClearanceMm,centerDistanceMm:distance,workingPressureAngleDeg:alpha*180/Math.PI,backlashMm:distance/(p.rp+q.rp)*(p.backlash+q.backlash)/2};
}

export function gearOperatingGeometry(p,q){
  if(p.profileShift+q.profileShift===0)return {alpha:p.alpha,distance:p.rp+q.rp};
  const inv=a=>Math.tan(a)-a,target=inv(p.alpha)+2*(p.profileShift+q.profileShift)*Math.tan(p.alpha)/(p.z+q.z);
  if(target<0)throw new Error('Combined profile shift leaves no working pressure angle');
  let lo=0,hi=Math.PI/2-1e-7;for(let i=0;i<70;i++){const mid=(lo+hi)/2;if(inv(mid)<target)lo=mid;else hi=mid;}
  const alpha=(lo+hi)/2;return {alpha,distance:(p.rb+q.rb)/Math.cos(alpha)};
}
